/**
 * Setup project: the seeded SUPER_ADMIN signs in through the admin MFA flow and the signed-in
 * session is stored for the specs that act as the admin.
 *
 * Fresh stack: password → email code → authenticator enrollment (secret read from the setup page,
 * codes generated by utils/totp.ts) → admin area. Later runs: password → TOTP code.
 */
import { expect, test as setup } from './utils/test';

import { adminCredentials, signInAdmin } from './utils/flows';
import { storageStatePath } from './utils/state';

setup(
  'super admin signs in with email code + TOTP and reaches the admin area',
  async ({ page }) => {
    const { email, password } = adminCredentials();
    const { enrolled } = await signInAdmin(page, email, password);
    setup.info().annotations.push({
      type: 'mfa',
      description: enrolled
        ? 'enrolled a new authenticator (email code + TOTP setup)'
        : 'verified with the stored authenticator',
    });

    await expect(page).toHaveURL(/\/admin\/?$/);
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
    // The admin API now accepts this session (TOTP-verified).
    const res = await page.request.get('/api/v1/admin/offerings?limit=1');
    expect(res.status()).toBe(200);

    await page.context().storageState({ path: storageStatePath('admin') });
  },
);
